
import numpy as np

DESCRIPTION = ("Mechanism. Step 1: h1 = |x1| * one-hot(sign(x1)) per unit, i.e. each unit starts as the positive or negative part of the first input "
               "(the input weights are pure signs - the gauge is chosen so they are exactly +-1, which is why they cost no constants). "
               "Steps 2-8: h_t = relu(h_{t-1}@Wh + x_t*signs); the recurrent matrix has complex-conjugate eigenvalue pairs (a damping/oscillatory "
               "mixture), the relus are active in almost every unit at almost every step, and the state grows multiplicatively (mean |h8| ~ 19, "
               "max 148): so the network propagates the 8 inputs through 7 recurrent steps and reads off 8 class scores. The decision is argmax_j "
               "(s_j - s_0) over the 7 score differences of the last state, i.e. a comparison of 8 oscillatory projections of the input history. "
               "Every recurrent weight and every readout entry matters and matters at the 1e-4 level: the class scores are near ties (margin 0.44 "
               "on a score scale of 6.6), so there is no threshold/count/max rule with fewer numbers - the 119 constants below are one per degree of "
               "freedom of the network (136 weights less the 8 hidden-unit scales and the 8 class-score shifts and 1 overall scale that leave its "
               "decisions unchanged), i.e. this is the maximally compressed exact description of the network.")

S = np.array([-1, 1, -1, -1, -1, 1, 1, 1])          # input weights in the hidden-unit gauge (signs only)
P = np.maximum(S, 0)
N = np.maximum(-S, 0)

WH = np.array([0.08166094869375229, 2.6567275516146602, 0.127566450707482, -1.8324145724988203, -0.286746167927924, 9.158416073947011, -0.10815537135410978, 35.871949470377615, -0.020105822540730536, 0.47973573207855225, -0.02099602146086777, 0.018890782258171698, 0.049884440061303895, -11.162491239265197, -0.021876488048755492, 14.489686027779833, 3.8781806737034374, -6.193329173863094, 0.2350926101207733, 0.2866830477248705, 2.320427052669432, 650.840506581114, 1.8770882925004029, -157.30447928301118, 0.8914694730096675, 9.749853708087336, -0.07307151205117869, -0.6714730858802795, -0.062492372218554096, 45.06939857652002, 0.040863832358503674, 4.320688142678695, -0.7173341405463166, -13.394256035296438, -0.17506621963840704, 3.9676956443581974, 0.27209100127220154, -6.154472091578441, 0.405679022207119, -48.13023316122699, -0.003346786383584853, -0.00246404030187275, -0.0008569504583482117, 0.02362847193042648, -0.004602260425571391, 0.7854707837104797, 0.004537450532980237, 0.5006406119228205, 4.178934235314999, -2.3523344640512778, 0.26385916061018955, 1.355365640547343, 1.6005847381785439, 112.2699901224643, 0.4884464740753174, -171.84185217038882, -0.004719161816865754, 0.10419153346164983, 0.00011052814474536725, 0.002750683413346949, -0.0020842712636466886, 0.34613257230375155, 0.011661737987549778, -0.6003977656364441]).reshape(8, 8)

# class scores minus score_0, in the same gauge (overall scale folded in; changes no decision)
K = np.array([0.5, 0.6092248395102516, 0.6731266554768384, 0.29407291955221204, 0.7235935808275245, 2.975911434765975, 0.48065657594238614, -0.08217760870924004, -0.10620110016098894, -0.13141931888562564, -0.28173132270416573, -0.1303936728777624, -0.04611199201269961, -0.08051637649507218, 1.3471975195772457, 0.1424685502707447, 1.8287271101583638, 4.029042629637245, 1.9022102550172708, 4.756117231399756, -24.898944282922837, -0.29132882389008236, -0.19440482197805192, -0.4529968139473073, -0.5172069215076202, -2.192809903891604, 0.6470974153144751, -0.2755602184578669, -1.2626917867434047, -0.7765300213176841, -0.8643372646456592, -0.16998660212288938, 0.6947853731386076, -6.322330255978549, -0.6515077253528331, -0.003125142419504521, 0.00035171888778150754, -0.0040495687545610785, -0.010090456996083911, -0.0045283295131248805, -0.047148426619629695, -0.0029687264591850265, 0.9971732648518856, -0.04496991891931686, 1.6062231784968823, 3.405180964629393, 1.6162017023739448, 1.3744841488109956, 1.0063741700279034, 0.0002886700049754916, 0.0013616600762673358, -0.012554331335814463, 0.0072121553347334515, 0.0006336921872139224, -0.006910244868617565, 0.0003209799024587211]).reshape(8, 7)

def model(x, iv):
    x = np.asarray(x)
    xp = iv("x1_pos", np.maximum(x[:, 0], 0.0))[:, None]
    xn = iv("x1_neg", np.maximum(-x[:, 0], 0.0))[:, None]
    h = xp * P + xn * N
    for t in range(2, 9):
        h = iv("h%d" % t, np.maximum(x[:, t - 1:t] * S + h @ WH, 0.0))
    return np.concatenate([np.zeros((h.shape[0], 1)), h @ K], axis=1)

ALIGN = {"x1_pos": ["h1"], "x1_neg": ["h1"]}
for t in range(2, 9):
    ALIGN["h%d" % t] = ["h%d" % t]
